def run_command(cmd):
    allowed = ['ls', 'git', 'make']
    parts = cmd.split()
    if not parts or parts[0] not in allowed:
        raise ValueError('Command not allowed')
    output = subprocess.check_output(parts, capture_output=True)
    return output.decode()

def scale_value(value, scale):
    if scale < 0 or scale > 30:
        raise ValueError('Scale out of allowed range')
    if value.bit_length() + scale > 31:
        raise OverflowError('Bit shift overflow')
    return value << scale
